#include <bits/stdc++.h>
using namespace std;

static vector<long long> sums(const vector<long long> &v) {
    vector<long long> s = {0};
    for (long long x : v) {
        size_t m = s.size();
        for (size_t i = 0; i < m; i++) s.push_back(s[i] + x);
    }
    sort(s.begin(), s.end());
    return s;
}

int main() {
    long long n, g;
    cin >> n >> g;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    vector<long long> L = sums(vector<long long>(a.begin(), a.begin() + n / 2));
    vector<long long> R = sums(vector<long long>(a.begin() + n / 2, a.end()));
    long long ans = llabs(g);
    long long i = 0, j = (long long)R.size() - 1;
    while (i < (long long)L.size() && j >= 0) {
        long long t = L[i] + R[j];
        ans = min(ans, llabs(t - g));
        if (t == g) break;
        if (t < g) i++;
        else j--;
    }
    printf("%lld\n", ans);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static long[] sums(long[] a, int from, int to) {
        long[] s = new long[1 << (to - from)];
        int m = 1;
        for (int k = from; k < to; k++) {
            for (int i = 0; i < m; i++) s[m + i] = s[i] + a[k];
            m *= 2;
        }
        Arrays.sort(s);
        return s;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long g = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long[] L = sums(a, 0, n / 2), R = sums(a, n / 2, n);
        long ans = Math.abs(g);
        int i = 0, j = R.length - 1;
        while (i < L.length && j >= 0) {
            long t = L[i] + R[j];
            ans = Math.min(ans, Math.abs(t - g));
            if (t == g) break;
            if (t < g) i++;
            else j--;
        }
        System.out.println(ans);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func sums(v []int64) []int64 {
	s := make([]int64, 1, 1<<len(v))
	for _, x := range v {
		m := len(s)
		for i := 0; i < m; i++ {
			s = append(s, s[i]+x)
		}
	}
	slices.Sort(s)
	return s
}

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	g := nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	L, R := sums(a[:n/2]), sums(a[n/2:])
	ans := abs(g)
	i, j := 0, len(R)-1
	for i < len(L) && j >= 0 {
		t := L[i] + R[j]
		ans = min(ans, abs(t-g))
		if t == g {
			break
		}
		if t < g {
			i++
		} else {
			j--
		}
	}
	fmt.Println(ans)
}
